package net.minecraft.client.gui.screens;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.*;import net.minecraft.client.gui.components.*;import net.minecraft.network.chat.Component;import java.util.*;public class Screen {protected int width=854,height=480;protected Font font=new Font();protected Minecraft minecraft=Minecraft.getInstance();private final List<AbstractWidget> widgets=new ArrayList<>();protected Screen(Component c){}protected void init(){}protected <T extends AbstractWidget> T addRenderableWidget(T w){widgets.add(w);return w;}protected void rebuildWidgets(){widgets.clear();init();}public void resize(Minecraft m,int w,int h){width=w;height=h;rebuildWidgets();}public void onClose(){minecraft.setScreen(null);}public boolean isPauseScreen(){return true;}public void render(GuiGraphics g,int x,int y,float t){}protected void renderBackground(GuiGraphics g){}public void tick(){}public boolean mouseClicked(double x,double y,int b){return false;}public List<AbstractWidget> children(){return widgets;}}